CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, name TEXT NOT NULL, phone TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, scope TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS roles(user_id TEXT NOT NULL REFERENCES users(id), role TEXT NOT NULL, PRIMARY KEY(user_id, role));
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires_at TEXT NOT NULL, revoked_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS campaigns(id TEXT PRIMARY KEY, name TEXT NOT NULL, starts_at TEXT NOT NULL, ends_at TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS intake_points(id TEXT PRIMARY KEY, name TEXT NOT NULL, scope TEXT NOT NULL, active INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS suggestions(id TEXT PRIMARY KEY, campaign_id TEXT NOT NULL REFERENCES campaigns(id), intake_point_id TEXT REFERENCES intake_points(id), author_id TEXT NOT NULL REFERENCES users(id), title TEXT NOT NULL, body TEXT NOT NULL, scope TEXT NOT NULL, status TEXT NOT NULL, version INTEGER NOT NULL, due_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS suggestion_events(id TEXT PRIMARY KEY, suggestion_id TEXT NOT NULL REFERENCES suggestions(id), from_status TEXT, to_status TEXT NOT NULL, actor_id TEXT NOT NULL REFERENCES users(id), note TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reviews(id TEXT PRIMARY KEY, suggestion_id TEXT NOT NULL REFERENCES suggestions(id), reviewer_id TEXT NOT NULL REFERENCES users(id), decision TEXT NOT NULL, note TEXT NOT NULL, version INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS departments(id TEXT PRIMARY KEY, name TEXT NOT NULL, scope TEXT NOT NULL, active INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS assignments(id TEXT PRIMARY KEY, suggestion_id TEXT NOT NULL REFERENCES suggestions(id), department_id TEXT NOT NULL REFERENCES departments(id), assignee_id TEXT REFERENCES users(id), status TEXT NOT NULL, lease_token TEXT, lease_until TEXT, version INTEGER NOT NULL, assigned_at TEXT NOT NULL, completed_at TEXT);
CREATE TABLE IF NOT EXISTS responses(id TEXT PRIMARY KEY, suggestion_id TEXT NOT NULL REFERENCES suggestions(id), author_id TEXT NOT NULL REFERENCES users(id), body TEXT NOT NULL, status TEXT NOT NULL, reviewed_by TEXT REFERENCES users(id), published_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS feedback(id TEXT PRIMARY KEY, suggestion_id TEXT NOT NULL REFERENCES suggestions(id), author_id TEXT NOT NULL REFERENCES users(id), rating INTEGER NOT NULL, comment TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notifications(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), suggestion_id TEXT REFERENCES suggestions(id), kind TEXT NOT NULL, payload TEXT NOT NULL, status TEXT NOT NULL, attempts INTEGER NOT NULL, next_attempt_at TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY, kind TEXT NOT NULL, payload TEXT NOT NULL, status TEXT NOT NULL, attempts INTEGER NOT NULL, run_after TEXT NOT NULL, lease_until TEXT, last_error TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_logs(id TEXT PRIMARY KEY, actor_id TEXT REFERENCES users(id), action TEXT NOT NULL, object_type TEXT NOT NULL, object_id TEXT NOT NULL, result TEXT NOT NULL, request_id TEXT NOT NULL, metadata TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS idempotency_keys(key TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), request_hash TEXT NOT NULL, response_json TEXT NOT NULL, created_at TEXT NOT NULL, expires_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_suggestions_scope_status ON suggestions(scope,status,updated_at);
CREATE INDEX IF NOT EXISTS idx_jobs_ready ON jobs(status,run_after);
CREATE INDEX IF NOT EXISTS idx_notifications_ready ON notifications(status,next_attempt_at);
